/** Valeur CSS / API pour un fond absent (logos). */
export const TRANSPARENT_COLOR = 'transparent';

export const PRESET_COLORS = [
  '#2563EB',
  '#0E7490',
  '#16A34A',
  '#CA8A04',
  '#C2410C',
  '#DC2626',
  '#DB2777',
  '#7C3AED',
  '#475569',
  '#0F172A',
] as const;

export function isTransparentColor(color: string): boolean {
  return color.trim().toLowerCase() === TRANSPARENT_COLOR;
}

export const ICON_CATALOG_COUNT = ICON_CATALOG.length;
